function clockMarkup(state,viewer,ctx){const {t,esc}=ctx;return `<section class="ui-staff-section"><div class="ui-staff-clock-banner"><div><span class="ui-staff-kicker">${esc(state.today)}</span><h2>${esc(state.currentTime)}</h2></div>${button('open-clock',t('打卡','Clock'),{id:viewer.id},ctx)}</div>${attendancePageMarkup(staffAttendanceModel(state),{...ctx,embedded:true})}</section>`;}

function dataTable(labels,rows,ctx){return rows.length?`<div class="ui-staff-table-wrap"><table class="ui-staff-table"><thead><tr>${labels.map(label=>`<th scope="col">${ctx.esc(label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,index)=>`<td data-label="${ctx.esc(labels[index])}">${ctx.esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<p class="ui-staff-empty-inline">${ctx.esc(ctx.t('暫時沒有紀錄。','No records yet.'))}</p>`;}
function leaveMarkup(state,viewer,ctx,{profile=false}={}){return leavePageMarkup(staffLeaveModel(state,{profileStaffId:profile?viewer.id:''}),{...ctx,embedded:true});}

function payrollMarkup(state,viewer,ctx){return payrollPageMarkup(staffPayrollModel(state),{...ctx,embedded:true});}

export function staffPortalMarkup(input={},suppliedContext){const state=normalized(input),ctx=context(suppliedContext),{t,esc}=ctx,viewer=state.viewer||memberFor(state,state.viewerId)||{id:state.viewerId||'',displayName:t('老師','Teacher')},tab=portalTabs.some(([key])=>key===state.portalTab)?state.portalTab:'home',tasks=list(state.todos).reduce((sum,category)=>sum+ownRows(category.tasks,viewer.id).filter(row=>!row.done).length,0);if(state.shared&&!state.sharedReady)return `<section class="ui-staff-page ui-staff-portal">${heading(t('我的工作台','My workspace'),viewer.displayName,'',ctx)}<div class="ui-staff-body">${sharedReadFeedback(state,'workspace',ctx)}</div></section>`;return `<section class="ui-staff-page ui-staff-portal">${heading(tab==='home'?t('我的工作台','My workspace'):t(...portalTabs.find(([key])=>key===tab).slice(1)),viewer.displayName,tab==='clock'?'':button('open-clock',t('打卡','Clock'),{id:viewer.id,secondary:true},ctx),ctx)}<div class="ui-staff-body">${feedback(state,ctx)}${sharedReadFeedback(state,'workspace',ctx)}<nav class="ui-staff-portal-tabs" aria-label="${esc(t('老師工作區','Teacher workspace'))}">${portalTabs.map(([key,zh,en])=>button('tab',t(zh,en)+(key==='todo'&&tasks?` (${tasks})`:''),{tab:key,secondary:true,extra:`aria-current="${tab===key?'page':'false'}"`},ctx)).join('')}</nav>${tab==='home'?`<div class="ui-staff-workspace-layout"><div>${todoMarkup(state,viewer,ctx)}</div><div>${classesMarkup(state,viewer,ctx)}</div></div>`:tab==='todo'?todoMarkup(state,viewer,ctx):tab==='classes'?classesMarkup(state,viewer,ctx):tab==='roster'?rosterPageMarkup(staffRosterModel(state),{...ctx,embedded:true}):tab==='clock'?clockMarkup(state,viewer,ctx):tab==='leave'?leaveMarkup(state,viewer,ctx):payrollMarkup(state,viewer,ctx)}</div></section>`;}
function field(name,label,value='',{type='text',required=false,options,maxLength=200}={},ctx){const {esc}=ctx;return `<label class="ui-staff-field"><span>${esc(label)}</span>${options?`<select name="${esc(name)}">${options.map(([key,text])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(text)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${esc(name)}" rows="3" maxlength="${maxLength}" ${type==='number'?'min="0" step="0.01"':''} ${required?'required':''}>${esc(value)}</textarea>`:`<input type="${type}" name="${esc(name)}" value="${esc(value)}" maxlength="${maxLength}" ${type==='number'?'min="0" step="0.01"':''} ${required?'required':''}>`}</label>`;}
function factsMarkup(facts,ctx){return `<dl class="ui-staff-detail-facts">${facts.map(([label,value])=>`<div><dt>${ctx.esc(label)}</dt><dd>${ctx.esc(value||'—')}</dd></div>`).join('')}</dl>`;}
function permissionFields(member,ctx,draft={}){const {t,esc}=ctx,permissions=member.permissions||permissionDefaults(member.role==='admin');const choices=[['none',t('不允許','No access')],['own',t('只限自己／獲指派','Own / assigned only')],['all',t('全部資料','All records')]];return `<div class="ui-staff-permissions"><div class="ui-staff-permission-head"><span>${esc(t('功能範圍','Module'))}</span><span>${esc(t('查看','Read'))}</span><span>${esc(t('修改','Edit'))}</span></div>${modules.map(([key,zh,en])=>`<fieldset class="ui-staff-permission-row"><legend>${esc(t(zh,en))}</legend>${['read','edit'].map(operation=>`<label><span>${esc(operation==='read'?t('查看','Read'):t('修改','Edit'))}</span><select name="${key}_${operation}" aria-label="${esc(t(zh,en)+' · '+(operation==='read'?t('查看','Read'):t('修改','Edit')))}">${choices.map(([value,label])=>`<option value="${value}" ${(draft[`${key}_${operation}`]??permissions[key]?.[operation]??'none')===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`).join('')}</fieldset>`).join('')}</div><p class="ui-staff-footnote">${esc(t('查看與修改權限可分開設定；「只限自己／獲指派」只涵蓋此員工負責的資料。','Set read and edit scopes separately. Own / assigned only covers records this staff member is responsible for.'))}</p>`;}
function sharedAccessSummary(state,member,ctx){
  const {t,esc}=ctx,linked=!!member.accountId,known=member.accountLinkKnown!==false,role=member.accountRole;
  const linkLabel=linked?t('已連結登入帳戶','Linked login account'):known?t('未連結登入帳戶','No linked login account'):t('由管理員查看登入連結','Login link available to administrators');
  const roleLabel=!linked?'—':role==='admin'?t('管理員','Administrator'):role==='teacher'?t('老師','Teacher'):t('角色資料待確認','Account role unavailable');
  const scope=!known&&!linked?t('登入連結及資料範圍由管理員管理。','An administrator manages login links and data access.'):!linked?t('此員工檔案尚未連結登入帳戶。連結後，課堂會按該帳戶的角色及授權顯示。','This staff profile has no linked login account. After linking, lessons follow the account role and authorized access.'):role==='admin'?t('管理員可管理中心資料及排課。','Administrators can manage centre data and schedules.'):role==='teacher'?t('老師可查看獲指派的課堂，以及管理員明確授權的課程、教學人員、課室或個別課堂。','Teachers can view their assigned lessons and lessons explicitly authorized through courses, teaching staff, rooms or individual lessons.'):t('已連結登入帳戶；實際資料範圍需在登入及課堂權限設定中確認。','A login account is linked. Review its actual scope in login and lesson access settings.');
  const enabled=state.viewer?.role==='admin'&&ctx.canManageStaffAccess;
  return `<section class="ui-staff-section"><div class="ui-staff-section-heading"><h3>${esc(t('登入及資料範圍','Login and data access'))}</h3></div>${factsMarkup([[t('登入連結','Login link'),linkLabel],[t('登入帳戶','Login account'),member.email||member.accountName||(linked?linkLabel:'—')],[t('帳戶角色','Account role'),roleLabel],[t('資料範圍','Data access'),scope]],ctx)}<p class="ui-staff-footnote">${esc(t('實際可查看的課堂由登入連結及已啟用的授權決定。','Visible lessons are determined by account links and active access grants.'))}</p>${button('open-permissions',t('設定登入及課堂權限','Manage login and lesson access'),{id:member.id,secondary:true,extra:enabled?'':`disabled title="${esc(t('目前無法開啟此設定','This setting is currently unavailable'))}"`},ctx)}${!enabled?`<p class="ui-staff-footnote">${esc(state.viewer?.role==='admin'?t('登入及課堂權限設定暫未提供。','Login and lesson access settings are currently unavailable.'):t('請聯絡管理員調整登入及課堂權限。','Contact an administrator to change login and lesson access.'))}</p>`:''}</section>`;
}
function permissionSummary(state,member,ctx){
  if(state.shared)return sharedAccessSummary(state,member,ctx);
  const {t,esc}=ctx;
  return `<div class="ui-staff-section-heading"><h3>${esc(t('工作權限','Work permissions'))}</h3>${button('open-permissions',t('設定權限','Set permissions'),{id:member.id,secondary:true},ctx)}</div>${factsMarkup(modules.map(([key,zh,en])=>[t(zh,en),`${t('查看','Read')}: ${scopeLabel(member.permissions?.[key]?.read||'none',t)} · ${t('修改','Edit')}: ${scopeLabel(member.permissions?.[key]?.edit||'none',t)}`]),ctx)}`;
}
function detailBody(state,member,tab,ctx){const {t,esc}=ctx;return `<div class="ui-staff-detail-identity">${avatar(member,ctx)}<div><h3>${esc(member.displayName)}</h3>${badges(member,ctx)}<p>${esc(words(member.position,t))}</p></div></div><nav class="ui-staff-detail-tabs" aria-label="${esc(t('員工資料分頁','Staff profile sections'))}">${detailTabs.map(([key,zh,en])=>button('detail-tab',key==='permissions'&&state.shared?t('登入及資料範圍','Login and data access'):t(zh,en),{id:member.id,tab:key,secondary:true,extra:`aria-current="${tab===key?'page':'false'}"`},ctx)).join('')}</nav>${tab==='contact'?staffProfilePageMarkup(staffProfileModel(state,{profileStaffId:member.id}),{...ctx,embedded:true,profile:true}):tab==='calendar-sharing'?calendarSharingPageMarkup(staffCalendarSharingModel(state,{profileStaffId:member.id}),{...ctx,embedded:true,profile:true}):tab==='permissions'?permissionSummary(state,member,ctx):tab==='salary'?salaryProfileMarkup(staffPayrollModel(state),member,ctx):tab==='roster'?rosterPageMarkup(staffRosterModel(state,{profileStaffId:member.id}),{...ctx,embedded:true,profile:true}):tab==='leave'?leaveMarkup(state,member,ctx,{profile:true}):tab==='teaching'?factsMarkup([[t('任教課程','Teaching courses'),(member.courses||[]).map(course=>words(course,t)).join(' · ')||t('待編排','To be arranged')],[t('僱傭安排','Employment'),member.employment==='full-time'?t('全職','Full-time'):member.employment==='part-time'?t('兼職','Part-time'):t('待確認','Pending confirmation')],[t('入職日期','Joined'),member.joined],[t('授課身份','Teaching identity'),member.teaching?t('可獲指派課堂','Available for teaching assignments'):t('行政工作','Administrative work')]],ctx):factsMarkup([[t('姓名','Name'),member.displayName],[t('電郵','Email'),member.email||'—'],...(member.shared?[[t('登入帳戶','Login account'),member.accountName||(member.accountId?t('已連結帳戶','Linked account'):t('未建立帳戶','No account created'))]]:[]),[t('電話','Phone'),member.phone],[t('職位','Position'),words(member.position,t)],[t('狀態','Status'),member.active===false?t('已停用','Inactive'):t('在職','Active')]],ctx)}`;}
const scopeLabel=(scope,t)=>scope==='all'?t('全部','All'):scope==='own'?t('自己／獲指派','Own / assigned'):t('不允許','No access');
function taskRecord(state,id){for(const category of list(state.todos)){const task=list(category.tasks).find(row=>row.id===id);if(task)return {task,category};}return null;}
export function staffWorkflowFacts(input={},id){const state=normalized(input),record=taskRecord(state,id);if(!record||record.task.staffId&&record.task.staffId!==state.viewerId)return null;const {task}=record,lesson=list(state.classes).find(row=>row.id===task.classId),teacher=memberFor(state,task.staffId);return {student:{id:task.studentId||`preview-${task.id}`,displayName:task.studentName,dateOfBirth:task.studentId==='chloe'?'2017-04-18':'',stage:record.category.id==='trial'?'Pending Follow-up':undefined},lesson:{id:lesson?.id||`preview-lesson-${task.id}`,courseName:lesson?words(lesson.courseName,(_zh,en)=>en):'藝術課程 / Art course',date:lesson?.date||task.due||state.today,time:lesson?.time||'13:00',teacher:teacher?.displayName||'',room:lesson?words(lesson.room,(_zh,en)=>en):'',duration:60}};}
function taskShortcuts(state,record,ctx){if(!record)return '';const {task,category}=record,{t}=ctx,workflow=(view,label)=>button('workflow',label,{id:task.id,secondary:true,extra:`data-ui-view="${view}"`},ctx);return `<div class="ui-staff-task-shortcuts">${['arrangements','attendance'].includes(category.id)?workflow('arrange','Make Up This Class')+workflow('message',t('傳訊息給家長','Send Message to Parent')):['trial','conversion'].includes(category.id)?workflow('applicant',t('試堂資料及跟進','Trial details and follow-up'))+workflow('convert','Convert to Student'):category.id==='payment'?button('open-payment',t('核對付款申請','Review payment request'),{id:task.id},ctx):''}</div>`;}
function prioritiesMarkup(state,ctx){const {t,esc}=ctx,rows=orderedTodos(state);return `<p class="ui-staff-footnote">${esc(t('預設將待安排課堂放在最前。使用上移／下移調整個人工作台的次序。','Pending class arrangements come first by default. Use Move up / down to personalize your workspace.'))}</p><ol class="ui-staff-priority-list">${rows.map((category,index)=>`<li><span class="ui-staff-drag-handle" aria-hidden="true"><i></i><i></i><i></i></span><div><strong>${esc(words(category.title,t))}</strong><small>${esc(t(`第 ${index+1} 位`,`Priority ${index+1}`))}</small></div><div class="ui-staff-priority-actions">${button('priority-up',t('上移','Move up'),{id:category.id,secondary:true,extra:`${index===0?'disabled ':''}aria-label="${esc(t('上移','Move up')+' · '+words(category.title,t))}"`},ctx)}${button('priority-down',t('下移','Move down'),{id:category.id,secondary:true,extra:`${index===rows.length-1?'disabled ':''}aria-label="${esc(t('下移','Move down')+' · '+words(category.title,t))}"`},ctx)}</div></li>`).join('')}</ol>${button('priorities-reset',t('還原預設次序','Reset priority order'),{secondary:true},ctx)}`;}
function paymentFor(state,id){return list(state.paymentRequests).find(row=>row.taskId===id||row.id===id);}
function paymentEditor(payment,draft,ctx){const {t,esc}=ctx;return `<div class="ui-staff-payment-state"><strong>${esc(payment.studentName)}</strong><span>${esc(payment.status==='awaiting-payment'?t('待付款 · 尚未確認收款','Awaiting payment · Unpaid'):t('待老師核對申請','Pending request review'))}</span></div><p class="ui-staff-footnote">${esc(t('Confirm Request 只確認訂單內容；不等於 Confirm Payment，也不會啟用課堂或標記已付款。','Confirm Request approves the order details. It is separate from Confirm Payment and does not activate lessons or mark payment received.'))}</p><div class="ui-staff-payment-items">${list(payment.items).map((item,index)=>`<fieldset><legend>${esc(t(`項目 ${index+1}`,`Item ${index+1}`))}</legend>${field(`item_${index}_name`,t('項目內容','Description'),draft[`item_${index}_name`]??item.name,{required:true},ctx)}<div class="ui-staff-form-grid">${field(`item_${index}_quantity`,t('數量','Quantity'),draft[`item_${index}_quantity`]??item.quantity,{type:'number',required:true},ctx)}${field(`item_${index}_price`,t('單價（港元）','Unit price (HKD)'),draft[`item_${index}_price`]??item.price,{type:'number',required:true},ctx)}</div></fieldset>`).join('')}</div><div class="ui-staff-form-grid">${field('finalAmount',t('最終金額（港元）','Final amount (HKD)'),draft.finalAmount??payment.finalAmount,{type:'number',required:true},ctx)}${field('dueDate',t('付款期限','Payment due date'),draft.dueDate??payment.dueDate,{type:'date',required:true},ctx)}${field('reminder',t('付款提醒','Payment reminder'),draft.reminder??payment.reminder,{options:[['none',t('不提醒','No reminder')],['due-date',t('到期當日','On the due date')],['three-days',t('到期前3日','3 days before due')]]},ctx)}</div>${field('note',t('備註（可選）','Note (optional)'),draft.note??payment.note,{type:'textarea',maxLength:1000},ctx)}<p class="ui-staff-footnote">${esc(t('此處只設定提醒時間，未寄出訊息。','This sets the reminder timing. No message has been sent.'))}</p>`;}
function paymentDocument(payment,ctx){const {t,esc}=ctx;return `<article class="ui-staff-payment-document"><header><span>BEAMAL ART STUDIO</span><h3>${esc(t('付款資料 · 草稿','Payment details · Draft'))}</h3></header>${factsMarkup([[t('學生','Student'),payment.studentName],[t('文件編號','Reference'),payment.reference||'—'],[t('付款期限','Payment due date'),payment.dueDate],[t('狀態','Status'),t('尚未付款','Unpaid')]],ctx)}${dataTable([t('項目','Description'),t('數量','Quantity'),t('金額','Amount')],list(payment.items).map(item=>[item.name,item.quantity,cash(item.quantity*item.price)]),ctx)}<p class="ui-staff-payment-total"><span>${esc(t('最終金額','Final amount'))}</span><strong>${esc(cash(payment.finalAmount))}</strong></p><p class="ui-staff-footnote">${esc(t('草稿文件，尚未確認收款。','Draft document. Payment has not been confirmed.'))}</p></article>`;}
export function staffDialogMarkup(input={},suppliedContext){const state=normalized(input),dialog=state.dialog;if(!dialog)return '';const ctx=context(suppliedContext),{t,esc}=ctx,kind=dialog.kind,member=kind==='leave'?leaveMember(state,dialog.id||state.viewerId):memberFor(state,dialog.id||state.viewerId),viewer=memberFor(state,state.viewerId)||{id:state.viewerId};let title='',body='',footer='',formKind='';
  if(['detail','permissions','edit','payroll','leave'].includes(kind)&&!member&&!(kind==='edit'&&dialog.id==='new')){title=t('員工資料未能提供','Staff profile unavailable');body=`<p>${esc(t('請關閉視窗，再選擇一位員工。','Close this dialog and select an available staff member.'))}</p>`;}
  else if(kind==='detail'){title=t('員工資料','Staff profile');body=detailBody(state,member,dialog.tab||'contact',ctx);footer=['contact','teaching'].includes(dialog.tab||'contact')?button('open-edit',t('編輯排課資料','Edit scheduling details'),{id:member.id},ctx):'';}
  else if(kind==='permissions'){if(state.shared){title=t('登入及資料範圍','Login and data access');body=`<p class="ui-staff-form-intro">${esc(member.displayName)}</p>${sharedAccessSummary(state,member,ctx)}`;}else{title=t('設定工作權限','Work permissions');formKind='permissions';body=`<p class="ui-staff-form-intro">${esc(member.displayName)}</p>${permissionFields(member,ctx,dialog.draft||{})}`;}}
  else if(kind==='edit'){title=dialog.id==='new'?t('新增員工','Add staff'):t('編輯員工資料','Edit staff profile');formKind='edit';const row={...(member||{}),...(dialog.draft||{})};body=`<div class="ui-staff-form-grid">${field('displayName',t('姓名','Display name'),row.displayName,{required:true},ctx)}${field('email',t('聯絡電郵','Contact email'),row.email,{type:'email'},ctx)}${field('phone',t('電話','Phone'),row.phone,{type:'tel'},ctx)}${field('position',t('職位','Position'),words(row.position,t),{},ctx)}${field('employment',t('僱傭安排','Employment'),row.employment||'',{options:[['',t('待確認','Pending confirmation')],['part-time',t('兼職','Part-time')],['full-time',t('全職','Full-time')]]},ctx)}${field('joined',t('入職日期','Joined'),row.joined,{type:'date'},ctx)}${field('courses',t('授課課程（以逗號分隔）','Teaching courses (comma-separated)'),typeof row.courses==='string'?row.courses:(row.courses||[]).map(course=>words(course,t)).join(', '),{},ctx)}${field('hourlyRate',t('時薪（港元）','Hourly rate (HKD)'),row.hourlyRate??'',{type:'number'},ctx)}</div><p class="ui-staff-footnote">${esc(t('登入帳戶及邀請需另外安排。','Login access and invitations are arranged separately.'))}</p>`;}
  else if(kind==='leave'){title=t('請假申請','Leave request');formKind='leave';body=`<p class="ui-staff-form-intro">${esc(member.displayName||'')}</p><div class="ui-staff-form-grid">${field('leaveType',t('假期類別','Leave type'),dialog.draft?.leaveType||'annual',{options:leaveTypes.map(([key,zh,en])=>[key,t(zh,en)])},ctx)}${field('from',t('開始日期','From'),dialog.draft?.from||state.today,{type:'date',required:true},ctx)}${field('to',t('結束日期','To'),dialog.draft?.to||state.today,{type:'date',required:true},ctx)}</div>${field('reason',t('原因及需要代課的安排','Reason and cover arrangements'),dialog.draft?.reason||'',{type:'textarea',required:true,maxLength:1000},ctx)}<p class="ui-staff-footnote">${esc(t('申請需經審批；涉及課堂時，請一併填寫代課安排。','Requests require approval. Include cover arrangements for any affected lessons.'))}</p>${state.shared?`<p id="ui-staff-leave-note" class="ui-staff-footnote">${esc(t('請假申請尚未接通；不會建立正式請假紀錄。','Leave requests are not connected yet. No leave record will be saved.'))}</p>`:''}`;}
  else if(kind==='clock'){title=t('打卡','Clock');formKind='clock';body=`<div class="ui-staff-clock-confirm"><span>${esc(state.today)}</span><strong>${esc(state.currentTime)}</strong><p>${esc((member||viewer).displayName||'')}</p></div>${field('note',t('備註（可選）','Note (optional)'),dialog.draft?.note||'',{type:'textarea',maxLength:500},ctx)}<p id="ui-staff-clock-note" class="ui-staff-footnote">${esc(t('打卡尚未接通；不會建立正式打卡紀錄。','Clock is not connected yet. No clock record will be saved.'))}</p>`;}
  else if(kind==='payroll'){title=t('薪金單','Payslip');body=`<div class="ui-staff-payslip-heading"><span>BEAMAL ART STUDIO</span><h3>${esc(member.displayName)}</h3>${state.shared?'':`<p>${esc(t('2026年10月 · 尚未發薪','October 2026 · No payment issued'))}</p>`}</div>${payrollMarkup(state,member,ctx)}`;}
  else if(kind==='priorities'){title=t('待辦優先次序','Priority settings');body=prioritiesMarkup(state,ctx);}
  else if(kind==='payment'||kind==='payment-document'){const payment=paymentFor(state,dialog.id);title=kind==='payment'?t('核對付款申請','Review payment request'):t('付款資料','Payment details');if(payment){if(kind==='payment'){formKind='payment';body=paymentEditor(payment,dialog.draft||{},ctx);footer=button('open-payment-document',t('查看付款文件','View payment document'),{id:dialog.id,secondary:true},ctx);}else body=paymentDocument(payment,ctx);}else body=`<p>${esc(t('暫未有此付款申請資料。','This payment request is unavailable.'))}</p>`;}
  else if(kind==='task'){const record=taskRecord(state,dialog.id),task=record?.task;title=t('跟進事項','Follow-up');body=task?`<div class="ui-staff-task-detail"><span class="ui-staff-kicker">${esc(task.studentName)}</span><h3>${esc(words(task.title,t))}</h3><p>${esc(words(task.detail,t))}</p><p>${esc(t('跟進日期','Follow up'))} · ${esc(task.due)}</p>${taskShortcuts(state,record,ctx)}</div>`:`<p>${esc(t('此事項已完成或不再提供。','This item is completed or unavailable.'))}</p>`;if(task)footer=`${task.classId?button('open-class',t('查看相關課堂','View related lesson'),{id:task.classId,secondary:true},ctx):''}${button('task-complete',t('標記已跟進','Mark reviewed'),{id:task.id},ctx)}`;}
  else if(kind==='class'){const lesson=list(state.classes).find(row=>row.id===dialog.id);title=t('課堂詳情','Lesson details');body=lesson?`<h3>${esc(words(lesson.courseName,t))}</h3>${factsMarkup([[t('日期及時間','Date and time'),`${lesson.date} · ${lesson.time}–${lesson.endTime}`],[t('課室','Room'),words(lesson.room,t)],[t('學生／班額','Students / capacity'),`${lesson.shared&&!lesson.rosterReady?'—':lesson.occupied??list(lesson.students).length} / ${lesson.capacity??'—'}`]],ctx)}<h3>${esc(t('學生名單','Student list'))}</h3>${lesson.shared&&!lesson.rosterReady?`<p role="status">${esc(t('學生名單尚未載入。','Student list not loaded.'))}</p>`:dataTable([t('學生','Student'),t('出席','Attendance')],list(lesson.students).map(row=>[row.displayName,({present:t('出席','Present'),absent:t('缺席','Absent'),late:t('遲到','Late'),sick:t('病假','Sick leave')})[row.attendance]||t('未登記','Unmarked')]),ctx)}`:`<p>${esc(t('暫時未能提供課堂資料。','Lesson details are unavailable.'))}</p>`;}
  else {title=t('工作台','Workspace');body=`<p>${esc(t('請返回工作台繼續。','Return to the workspace to continue.'))}</p>`;}
  const saveLabel=kind==='payment'?t('確認申請','Confirm Request'):kind==='leave'?t('提交申請','Submit request'):kind==='clock'?t('確認','Confirm'):t('儲存','Save');
  return `<div class="modal ui-staff-modal" role="dialog" aria-modal="true" aria-labelledby="ui-staff-dialog-title"><div class="dialog ui-staff-dialog" tabindex="-1"><header><div><h2 id="ui-staff-dialog-title">${esc(title)}</h2></div>${button('close-dialog','×',{secondary:true,extra:`aria-label="${esc(t('關閉','Close'))}"`},ctx)}</header>${formKind?`<form id="ui-staff-form" data-ui-form="${formKind}" data-ui-id="${esc(dialog.id||state.viewerId)}">`:''}<div class="ui-staff-dialog-body">${feedback(state,ctx)}${sharedReadFeedback(state,'staff',ctx)}${body}</div><footer>${button('close-dialog',t('關閉','Close'),{secondary:true},ctx)}${formKind?`${footer}<button class="ui-staff-button" type="submit"${(kind==='clock'||kind==='leave')?` disabled aria-describedby="ui-staff-${kind}-note"`:''}>${esc(saveLabel)}</button>`:footer}</footer>${formKind?'</form>':''}</div></div>`;
}
export function advanceStaffPreview(input={},command,fields={}) {
  const state=structuredClone(normalized(input)),id=fields.id||fields.uiId||state.viewerId;state.error='';state.notice='';
  if(command==='open-leave'&&!leaveMember(state,id)){state.error='假期資料暫未提供 / Leave details are unavailable.';return state;}
  const openings={'open-detail':'detail','open-edit':'edit','open-permissions':'permissions','open-leave':'leave','open-clock':'clock','open-task':'task','open-class':'class','open-payroll':'payroll','export-payroll':'payroll','open-priorities':'priorities','open-payment':'payment','open-payment-document':'payment-document'};
  if(openings[command])state.dialog={kind:openings[command],id:command==='open-edit'?(fields.id||'new'):id,tab:fields.tab||'contact',...(command==='open-clock'?{mode:state.clockedIn?'out':'in'}:{}),...(command==='open-permissions'?{returnTo:{kind:'detail',id,tab:'permissions'}}:{})};
  else if(command==='close-dialog')state.dialog=state.dialog?.returnTo||null;
  else if(command==='tab'){state.portalTab=fields.tab||fields.value||'home';state.dialog=null;}
  else if(command==='detail-tab')state.dialog={kind:'detail',id,tab:fields.tab||'contact'};
  else if(command==='filter'){state.filter=fields.tab||fields.value||'all';state.page=1;}
  else if(command==='search'){state.query=String(fields.value??'');state.page=1;}
  else if(command==='page')state.page=Math.max(1,Number(fields.tab||fields.value)||1);
  else if(command==='clock-in'||command==='clock-out')state.dialog={kind:'clock',id,mode:command==='clock-out'?'out':'in'};
  else if(command==='priority-up'||command==='priority-down'||command==='priorities-reset'){const order=(command==='priorities-reset'?list(state.todos).slice().sort((a,b)=>(a.id==='arrangements'?-1:b.id==='arrangements'?1:0)):orderedTodos(state)).map(row=>row.id),index=order.indexOf(id),target=index+(command==='priority-up'?-1:1);if(command!=='priorities-reset'&&index>=0&&target>=0&&target<order.length)[order[index],order[target]]=[order[target],order[index]];state.todoPriorityOrder=order;state.todoPriorityByStaff={...(state.todoPriorityByStaff||{}),[state.viewerId]:order};state.dialog={kind:'priorities',id:state.viewerId};}
  else if(command==='task-complete'){state.todos=list(state.todos).map(category=>({...category,tasks:list(category.tasks).map(task=>task.id===id?{...task,done:true}:task)}));state.dialog=null;state.notice='本次示範已更新 / Updated for this demonstration.';}
  else if(command==='submit'){
    const formKind=fields.formKind||state.dialog?.kind,targetId=state.dialog?.id||id,member=memberFor(state,targetId);if(state.dialog)state.dialog.draft={...fields};
    if(formKind==='edit'){
      if(state.shared){state.error='請返回員工資料重新開啟編輯 / Reopen this staff member to edit the shared record.';return state;}
      if(!String(fields.displayName||'').trim()){state.error='請填寫姓名 / Enter a display name.';return state;}
      const rate=Number(fields.hourlyRate||0);if(!Number.isFinite(rate)||rate<0){state.error='請填寫有效時薪 / Enter a valid hourly rate.';return state;}
      const patch={displayName:String(fields.displayName).trim(),email:String(fields.email||'').trim(),phone:String(fields.phone||'').trim(),position:String(fields.position||'').trim(),employment:['full-time','part-time'].includes(fields.employment)?fields.employment:'',joined:String(fields.joined||''),courses:String(fields.courses||'').split(/[,，]/).map(value=>value.trim()).filter(Boolean),hourlyRate:rate};
      if(member)state.staff=state.staff.map(row=>row.id===targetId?{...row,...patch}:row);else state.staff.push({...patch,id:`preview-staff-${state.staff.length+1}`,role:'teacher',teaching:true,active:true,previewOnly:true,permissions:permissionDefaults(false)});
    }else if(formKind==='permissions'){
      if(state.shared){state.error='請使用登入及課堂權限設定 / Use login and lesson access settings.';return state;}
      const permissions=Object.fromEntries(modules.map(([key])=>[key,Object.fromEntries(['read','edit'].map(operation=>[operation,['own','all'].includes(fields[`${key}_${operation}`])?fields[`${key}_${operation}`]:'none']))]));state.staff=state.staff.map(row=>row.id===targetId?{...row,permissions}:row);
    }else if(formKind==='leave'){
      state.error='請假申請尚未接通，未建立正式紀錄 / Leave requests are not connected; no leave record was saved.';return state;
    }else if(formKind==='payment'){
      const payment=paymentFor(state,targetId),finalAmount=Number(fields.finalAmount),items=list(payment?.items).map((item,index)=>({...item,name:String(fields[`item_${index}_name`]??item.name).trim(),quantity:Number(fields[`item_${index}_quantity`]??item.quantity),price:Number(fields[`item_${index}_price`]??item.price)}));
      if(!payment||!Number.isFinite(finalAmount)||finalAmount<0||!validDate(fields.dueDate)||items.some(item=>!item.name||!Number.isFinite(item.quantity)||item.quantity<=0||!Number.isFinite(item.price)||item.price<0)){state.error='請檢查項目、金額及付款期限 / Check the items, amount and due date.';return state;}
      state.paymentRequests=state.paymentRequests.map(row=>row.id===payment.id?{...row,items,finalAmount,dueDate:fields.dueDate,reminder:['due-date','three-days'].includes(fields.reminder)?fields.reminder:'none',note:String(fields.note||''),status:'awaiting-payment',paid:false}:row);
    }else if(formKind==='clock'){
      state.error='打卡尚未接通，未建立正式紀錄 / Clock is not connected; no clock record was saved.';return state;
    }
    state.dialog=formKind==='permissions'?{kind:'detail',id:targetId,tab:'permissions'}:null;state.notice=formKind==='permissions'?'本次示範已更新，尚未套用至登入帳戶 / Updated for this demonstration; login access is unchanged.':'本次示範已更新 / Updated for this demonstration.';
  }
  return state;
}
